 "웹훅을 추가했어요. '시험 보내기'로 확인해 보세요.": "已新增 Webhook。請用「測試傳送」確認看看。",
 "이 서버는 아직 웹훅을 지원하지 않아요. 서버를 새 버전으로 올려 주세요.": "這個伺服器還不支援 Webhook。請將伺服器更新到新版本。",
 "웹훅은 사람 계정으로 로그인했을 때만 보고 바꿀 수 있어요.": "只有以個人帳號登入時,才能查看和修改 Webhook。",
