 "이 계정에는 기억을 밖으로 내보낼 권한이 없어요. 서버 관리자에게 'external:space_bundle' 권한을 받아 주세요.": "這個帳號沒有匯出記憶的權限。請向伺服器管理員索取 'external:space_bundle' 權限。",
 "Arkism에서 내보낸 기억 공간 파일인지 확인해 주세요.": "請確認這是從 Arkism 匯出的記憶空間檔案。",
 "파일이 너무 커요. 8MB까지 가져올 수 있어요.": "檔案太大了。最多可匯入 8MB。",
