 "내보낼 파일을 만드는 중…": "正在建立要匯出的檔案…",
 "파일 다운로드를 시작했어요. 다른 Arkism의 설정 › 고급에서 가져오세요. 기억 내용이 들어 있으니 안전한 곳에 두세요.": "已開始下載檔案。請到另一個 Arkism 的 設定 › 進階 匯入。檔案內含記憶內容,請妥善保管。",
 "이 파일의 기억을 가져올까요? 바로 저장되지 않고 모두 '확인해 주세요'에 후보로 들어가요.": "要匯入這個檔案中的記憶嗎?不會直接儲存,全部都會以候選的形式進入「請確認」。",
