 "이 공간의 기억을 파일로 내보내거나, 받은 파일을 가져와요. 가져온 기억은 내가 확인해야 저장돼요.": "可將這個空間的記憶匯出成檔案,或匯入收到的檔案。匯入的記憶要經過你確認才會儲存。",
