 "에이전트를 다시 연결했어요. 열려 있는 에이전트는 다시 시작하세요.": "已重新連接代理。已開啟的代理請重新啟動。",
 "다시 연결하지 못했어요. 설정 › 고급 › 진단에서 점검해 보세요.": "無法重新連線。請到 設定 › 進階 › 診斷 檢查看看。",
 "에이전트 설정 파일을 고치지 못해 대화를 모으지 못해요.": "無法修改代理程式的設定檔，所以無法收集對話。",
