 "에이전트가 처음 보고하면 여기에 보여요.": "代理程式第一次回報後，就會顯示在這裡。",
 "평소처럼 대화하기": "照平常方式對話",
 "에이전트와 평소처럼 대화하면, 대화가 끝나고 몇 분 뒤 기억 후보가 여기 와요. 내가 승인한 것만 저장돼요.": "照平常的方式和代理程式對話，對話結束幾分鐘後，記憶候選就會出現在這裡。只有您核准的才會儲存。",
