 "이 PC용 Arkism 파일을 찾지 못했어요. 앱을 다시 설치하면 고쳐져요.": "找不到這台電腦專用的 Arkism 檔案。重新安裝 App 就能修好。",
 "기억을 저장할 곳을 만들지 못했어요. 저장 폴더에 쓸 수 있는지, 디스크가 꽉 차지 않았는지 확인하세요.": "無法建立儲存記憶的位置。請確認儲存資料夾是否可寫入，以及磁碟是否已滿。",
 "기억 저장소를 켜지 못했어요. 앱을 모두 닫았다가 다시 열어 보세요.": "無法啟動記憶儲存庫。請完全關閉 App 後再重新開啟。",
 "Arkism을 켜지 못했어요. 다른 Arkism 창이 열려 있으면 닫고 다시 시도하세요.": "無法啟動 Arkism。如果有其他 Arkism 視窗開著，請先關閉再重試。",
