 "이 PC의 접속 열쇠가 취소됐어요. 다시 시도하면 새로 만들어요.": "這台電腦的存取金鑰已被撤銷。再試一次就會重新建立。",
 "모델 연결 기능을 켜지 못했어요.": "無法啟動模型連線功能。",
 "저장 폴더를 만들지 못했어요. 폴더 권한과 남은 디스크를 확인하세요.": "無法建立儲存資料夾。請確認資料夾權限和剩餘的磁碟空間。",
 "켜는 중에 문제가 생겼어요.": "啟動時發生問題。",
