 "점검하고 고치는 중…": "正在檢查並修復…",
 "점검하지 못했어요. 기록 폴더의 파일을 문의할 때 같이 보내 주세요.": "無法完成檢查。聯絡我們時，請一併附上記錄資料夾裡的檔案。",
 "기록 폴더를 열지 못했어요.": "無法開啟記錄資料夾。",
 "자세히 (저장 위치)": "更多（儲存位置）",
 "점검하고 고치기": "檢查並修復",
 "기록 폴더 열기": "開啟記錄資料夾",
 "서버에 Arkism이 설치돼 있어야 해요. 포트는 따로 열지 않아도 돼요. SSH 키나 비밀번호로 접속되면 이 앱이 나머지를 해요.": "伺服器上必須已安裝 Arkism。不需要另外開放連接埠。只要能用 SSH 金鑰或密碼登入，其餘就由這個 App 處理。",
 "서버에 설치하는 방법 ›": "如何安裝在伺服器上 ›",
