 "그 전 30일보다": "與前 30 天相比",
 "응답 시간": "回應時間",
 "느릴 때": "較慢時",
 "보통 / 느릴 때": "一般 / 較慢時",
 "이 서버는 아직 라우팅을 지원하지 않아요. 서버에 모델 라우터가 연결되면 여기서 요청 수·응답 시간·성공률·비용을 볼 수 있어요.": "這台伺服器還不支援路由功能。伺服器連上模型路由器後，就能在這裡看到請求數、回應時間、成功率和費用。",
