 "짧은 질문": "簡短問題",
 "위에 해당하지 않는 짧은 요청(80자 이하)": "不屬於以上類別的簡短請求（80 字以內）",
 "이 기간에는 라우터를 거친 요청이 없어요": "這段期間沒有經過路由器的請求",
 "에이전트(Claude Code·Codex·Gemini CLI)를 연결하면 요청이 라우터를 거쳐 알맞은 모델로 가고, 여기에 요청 수·응답 시간·비용이 나와요.": "連接代理程式（Claude Code、Codex、Gemini CLI）後，請求會經過路由器送到合適的模型，請求數、回應時間和費用就會顯示在這裡。",
 "에이전트 연결하기": "連接代理程式",
