 "판정 모델 정하기": "設定評判模型",
 "꺼져 있어요. 모든 요청이 기본 모델로 가요.": "已關閉。所有請求都會送到預設模型。",
 "켜져 있지만 판정 모델이 없어요.": "已開啟，但沒有評判模型。",
 "기본 모델 (자동 라우팅을 껐거나 판정 모델이 고르지 못할 때)": "預設模型（自動路由關閉，或評判模型無法選擇時）",
 "고른 모델이 답을 시작하기 전에 거절되면 바로 다음 모델로 넘겨요. 답을 쓰던 중에 끊긴 요청은 넘기지 않아요.": "如果所選模型在開始回答前就拒絕，請求會直接轉給下一個模型。回答到一半中斷的請求不會轉出去。",
 "1번 모델부터 차례로": "從模型 1 開始依序",
 "한도나 크레딧이 떨어져 거절된 모델은 잠시 쉬며 맨 뒤로 가요. 요청 하나로 먼저 확인한 뒤 돌아와요.": "因額度或點數用完而被拒絕的模型，會先休息一下並排到最後。用一次請求確認後才會回來。",
 "실패가 이보다 잦으면 라우팅 현황에 '주의' 표시": "失敗比這個比例更頻繁時，在路由狀態顯示「注意」",
 "느릴 때 응답 시간이 이보다 길면 '느림' 표시": "較慢時的回應時間比這個更長時，顯示「慢」",
 "자세히 · 넘기는 순서와 표시 기준": "更多 · 轉交順序與顯示標準",
 "넘기는 설정을 바꿨어요. 저장해야 적용돼요.": "您已變更轉交設定。需要儲存才會生效。",
 "이런 일은 늘 이 모델로": "這類工作一律使用此模型",
 "넘기는 설정 저장": "儲存轉交設定",
 "요청에 든 낱말로 일의 종류를 알아보고, 정한 모델로 바로 보내요. 판정 모델보다 먼저 쓰고, 자동 라우팅이 켜져 있을 때만 써요.": "根據請求中的字詞判斷工作類型，並直接送到指定的模型。會比評判模型優先使用，而且只在自動路由開啟時才會使用。",
 "판정 모델에 맡기기": "交給評判模型",
 "따로 정하지 않음": "不另外指定",
 "자동 라우팅을 껐어요. 모든 요청이 기본 모델로 가요.": "自動路由已關閉。所有請求都會送到預設模型。",
 "켠 모델이 없어요. 설정 › 에이전트에서 모델을 켜면 여기에 나와요.": "沒有已開啟的模型。到 設定 › 代理程式 開啟模型後，就會顯示在這裡。",
 "저장 안 함": "不儲存",
 "예: 코드를 고치거나 테스트를 쓸 때": "例：修改程式碼或撰寫測試時",
 "이럴 때 보내요": "符合這些情況時送到這裡",
 "1번 모델이 기본으로 가고, 실패하면 다음 번호로 넘겨요.": "預設使用模型 1，失敗時會轉給下一個編號。",
 "자세히 · 한도": "更多 · 限制",
 "한도를 넘으면 그룹에서는 다음 모델로 넘기고, 아니면 잠깐 뒤에 다시 하라고 알려요. 비우거나 0이면 제한이 없어요.": "超過限制時，群組會轉給下一個模型；否則會通知代理程式稍後再試。留空或填 0 代表沒有限制。",
 "이 모델을 바꿨어요. 저장해야 적용돼요.": "您已變更這個模型。需要儲存才會生效。",
