 "교훈을 읽지 못했어요. 권한과 서버 버전을 확인해 주세요.": "無法讀取教訓。請確認權限和伺服器版本。",
 "평가 과제는 데스크톱 앱이 평가 서버에서 불러와요. 데스크톱 앱에서 열어 주세요.": "評估任務是由桌面版 App 從評估伺服器載入的。請在桌面版 App 中開啟。",
 "평가 서버가 평가 설정을 보내지 않았어요. 평가 서버의 Arkism 설정을 확인해 주세요.": "評估伺服器沒有傳來評估設定。請確認評估伺服器上的 Arkism 設定。",
 "평가 서버에 등록된 평가 과제가 없어요. 평가 서버 설정에 과제를 하나 등록하면 자동으로 채워져요.": "評估伺服器上沒有已登錄的評估任務。在評估伺服器設定中登錄一個任務，這裡就會自動填入。",
 "평가 서버의 Arkism이 오래돼 통과 기준을 주지 않아요. 평가 서버를 업데이트하면 자동으로 채워져요.": "評估伺服器上的 Arkism 版本太舊，無法提供通過標準。更新評估伺服器後就會自動填入。",
 "아직 개선안을 만들 수 없어요.": "目前還無法建立改善方案。",
