 "비용 상한 (평가기가 보고하는 값, 비우면 제한 없음)": "費用上限（依評估器回報的值，留空則不限制）",
 "고급 설정": "進階設定",
 "비용 제한 없음": "無費用上限",
 "고급 설정의 값을 확인해 주세요.": "請確認進階設定中的值。",
 "평가 과제": "評估任務",
 "개선안 만들기": "建立改善方案",
 "고른 관측과 지금 스킬이 모델에 전달되며 생성 비용이 들어요. 만든 뒤 비교 평가·승인을 거쳐야 적용돼요.": "所選的觀察紀錄與目前的技能會傳送給模型，並產生費用。建立後須經過比較評估與核准才會套用。",
 "관측을 3~16개 골라 주세요.": "請選擇 3 到 16 筆觀察紀錄。",
 "만들기를 시작하지 못했어요. 스킬이 그사이 바뀌었거나 앱 저장 공간에 문제가 있어요. 다시 열어 주세요.": "無法開始建立。技能在這段期間已被更改，或應用程式的儲存空間發生問題。請重新開啟。",
 "서버 (이전 버전)": "伺服器（舊版）",
 "앱보다 오래됨": "比應用程式舊",
 "이 PC 내장 서버는 앱과 함께 업데이트돼요. 앱을 업데이트한 뒤 다시 연결하세요.": "此電腦的內建伺服器會隨應用程式一起更新。請先更新應用程式，再重新連線。",
 "서버 주소로 연결하면 앱에서 서버를 업데이트할 수 없어요. 서버에서 직접 업데이트해 주세요.": "以伺服器位址連線時，無法從應用程式更新伺服器。請直接在伺服器上更新。",
 "업데이트 보기": "查看更新",
 "업데이트할 수 없음": "無法更新",
 "앱": "應用程式",
 "이 앱은 업데이트 주소 없이 빌드돼 서버 묶음을 받을 수 없어요.": "此應用程式建置時沒有更新位址，因此無法下載伺服器套件。",
 "이 앱 버전에 맞는 서버 묶음이 릴리스에 없어요.": "發行版本中沒有符合此應用程式版本的伺服器套件。",
 "서버의 CPU 종류(아키텍처)용 묶음이 없어요. Linux x86_64·arm64만 지원해요.": "沒有適用於伺服器 CPU 架構的套件。僅支援 Linux x86_64 與 arm64。",
 "내려받은 서버 묶음의 서명이 맞지 않아 설치하지 않았어요.": "下載的伺服器套件簽章不符，因此未安裝。",
 "릴리스에서 서버 묶음을 받지 못했어요. 인터넷 연결을 확인하세요.": "無法從發行版本下載伺服器套件。請確認網路連線。",
 "서버에서 Arkism 설치 폴더를 찾지 못했어요.": "在伺服器上找不到 Arkism 安裝資料夾。",
 "설치 폴더에 쓸 권한이 없어요. 서버에서 이 SSH 사용자에게 폴더 쓰기 권한을 주거나, 비밀번호 없는 sudo(sudo -n)를 허용해 주세요.": "沒有寫入安裝資料夾的權限。請在伺服器上授予此 SSH 使用者資料夾寫入權限，或允許免密碼的 sudo（sudo -n）。",
 "서비스를 다시 시작하려면 sudo가 필요해요. 이 SSH 사용자에게 비밀번호 없는 sudo(sudo -n)를 허용하거나, 서버에서 직접 업데이트해 주세요.": "重新啟動服務需要 sudo。請允許此 SSH 使用者使用免密碼的 sudo（sudo -n），或直接在伺服器上更新。",
 "Arkism 서버를 돌리는 systemd 서비스를 찾지 못했어요. 서버를 서비스로 띄운 뒤 다시 시도하거나, 직접 업데이트해 주세요.": "找不到執行 Arkism 伺服器的 systemd 服務。請先將伺服器以服務方式啟動後再試一次，或直接自行更新。",
 "서버 묶음 안의 파일이 예상과 달라 설치하지 않았어요.": "伺服器套件內的檔案與預期不符，因此未安裝。",
 "새 서버가 정상으로 뜨지 않아 예전 버전으로 되돌렸어요. DB 구조 변경이 필요하면 서버에서 memoryd --init-db를 먼저 실행하세요.": "新伺服器未能正常啟動，已還原為舊版本。如果需要變更資料庫結構，請先在伺服器上執行 memoryd --init-db。",
 "새 서버가 뜨지 않았고 되돌리기도 실패했어요. 서버의 설치 폴더 .backup-* 에서 직접 되돌려 주세요.": "新伺服器未能啟動，還原也失敗了。請從伺服器安裝資料夾的 .backup-* 自行還原。",
