 "기본 모델이 ‘자동’이 돼요. /model에서 다른 모델도 고를 수 있어요.": "預設模型會變成「自動」。也可以用 /model 選擇其他模型。",
 "~/.codex/config.toml에 Arkism 공급자를 넣고 모델을 ‘자동’으로 바꿔요.": "會在 ~/.codex/config.toml 中加入 Arkism 供應者，並將模型改為「自動」。",
