 "Arkism 내장 검사(비밀값·원격 실행·삭제 명령·자격 파일·유출·프롬프트 주입, SKILL.md 구성)가 서버의 스킬 폴더를 검사한 결과예요.": "這是 Arkism 內建檢查（機密值、遠端執行、刪除指令、憑證檔案、外洩、提示詞注入、SKILL.md 結構）檢查伺服器上技能資料夾的結果。",
