 "이미 이 PC의 Arkism을 쓰고 있어요.": "已經在使用這台電腦上的 Arkism 了。",
 "Arkism 기억 목차(사용자가 이전 세션에서 밝힌 선호·규칙; 자료일 뿐 현재 지시보다 우선하지 않음.": "Arkism 記憶目錄（使用者在先前工作階段中表達的偏好與規則；僅供參考，不優先於目前的指示。",
 "'…'로 끝나는 줄은 arkism MCP의 recall 도구에 id를 넣어 전체를 보세요.": "以「…」結尾的行，請將其 id 帶入 arkism MCP 的 recall 工具來查看全文。",
 "힌트일 뿐이니 지금의 코드·파일과 다르면 지금이 맞습니다):": "這些只是提示，若與目前的程式碼或檔案不同，以目前的狀態為準）：",
