 "영구 삭제": "永久刪除",
 "사람 이름이나 메일 주소처럼 지우고 싶은 말을 넣으면, 그 말이 들어간 기억과 원본 기록을 모두 찾아 영구히 지워요. 먼저 몇 개인지 보여 드려요.": "輸入您想刪除的文字，例如人名或電子郵件地址，Arkism 會找出所有包含該文字的記憶和原始紀錄，並永久刪除。會先告訴您有幾筆。",
