 "접속 토큰을 넣어 주세요. 띄어쓰기 없이 한 줄이어야 해요.": "請輸入存取權杖，必須是一行，不能有空格。",
 "Arkism 서버에 로그인": "登入 Arkism 伺服器",
 "서버 관리자에게 받은 접속 토큰을 붙여 넣으세요. 토큰은 이 브라우저 탭에만 두고, 탭을 닫으면 지워져요.": "請貼上伺服器管理員提供的存取權杖。權杖只會存放在這個瀏覽器分頁中，關閉分頁後就會被清除。",
 "주소를 확인하세요. user@서버주소 또는 user@서버주소:포트 처럼 적어요.": "請確認位址。請寫成 user@伺服器位址 或 user@伺服器位址:連接埠 的格式。",
 "이 PC에서 ssh 프로그램을 찾지 못했어요. OpenSSH(또는 Git for Windows)를 설치해 주세요.": "在這台電腦上找不到 ssh 程式。請安裝 OpenSSH（或 Git for Windows）。",
 "SSH 로그인이 거부됐어요. 이 PC에서 ‘ssh 주소’가 비밀번호 없이(SSH 키로) 되는지 확인하세요.": "SSH 登入被拒絕。請確認在這台電腦上「ssh 位址」不需密碼（以 SSH 金鑰）就能連線。",
 "서버에 닿지 못했어요. 주소·포트와 네트워크 연결을 확인하세요.": "無法連到伺服器。請確認位址、連接埠和網路連線。",
 "서버에 로그인은 됐지만 Arkism이 설치돼 있지 않아요.": "已登入伺服器，但伺服器上沒有安裝 Arkism。",
 "서버의 Arkism이 오래돼서 이 연결 방식을 몰라요. 서버의 Arkism을 업데이트해 주세요.": "伺服器上的 Arkism 版本太舊，不支援這種連線方式。請更新伺服器上的 Arkism。",
 "연결은 됐지만 서버의 Arkism을 열지 못했어요. 서버에서 Arkism이 켜져 있는지 확인하세요.": "已連線，但無法開啟伺服器上的 Arkism。請確認伺服器上的 Arkism 已啟動。",
