 "노드를 누르면 여기서 고쳐요. 출력 점을 끌어 다음 노드에 이어요. 앞 노드로 이으면 되돌아가는 선이 돼요. 선을 누르면 선 설정이 열려요. 휠로 확대·축소하고, 휠 클릭이나 스페이스를 누른 채 끌면 화면이 움직여요.": "點選節點即可在這裡編輯。拖曳輸出點可連到下一個節點;連到前面的節點就會變成回到前面的連線。點一下連線可開啟連線設定。滾動滾輪可縮放,按住滾輪或按住空白鍵拖曳可移動畫面。",
 "노드": "節點",
 "되돌아가는 선": "回到前面的連線",
 "고르세요": "請選擇",
 "출력이 {\"ok\": true/false, …}면 통과·실패 갈래로 나뉘어요. 처음 한 번은 빌드에 1~2초, 30초 안에 끝나야 해요. 토큰은 들지 않아요.": "如果輸出是 {\"ok\": true/false, …},就會分成通過與失敗兩個分支。第一次執行時建置需要 1~2 秒,且必須在 30 秒內完成。不會消耗 token。",
 "배포·게시처럼 되돌릴 수 없는 단계 바로 앞에 두세요. 답이 올 때까지 멈춰요.": "請放在部署、發布這類無法復原的步驟之前。在收到回覆前會先暫停。",
