 "비밀번호 로그인이 거부됐어요. 비밀번호를 확인하세요. 서버가 비밀번호 로그인을 막아 두었으면 SSH 키가 필요해요.": "密碼登入被拒絕。請確認密碼。如果伺服器封鎖了密碼登入，就需要 SSH 金鑰。",
 "비밀번호 로그인이 거부됐어요": "密碼登入被拒絕",
 "비밀번호를 넣어 주세요.": "請輸入密碼。",
 "인증 방식": "驗證方式",
 "SSH 키": "SSH 金鑰",
 "비밀번호": "密碼",
 "연결되면 이 PC의 키체인(자격 증명 관리자)에 저장해 다시 묻지 않아요. 비워 두면 저장된 비밀번호를 써요": "連線成功後會儲存在這台電腦的金鑰鏈（認證管理員），就不會再詢問。留空則使用已儲存的密碼",
 "서버의 Git·스킬 화면은 이 연결로 돼요. 에이전트의 기억 수집은 SSH 키가 있어야 서버로 가요.": "伺服器的 Git 和技能畫面會使用這個連線。代理程式的記憶蒐集需要有 SSH 金鑰才能傳到伺服器。",
 "SSH 키 또는 ssh-agent로 로그인해요": "使用 SSH 金鑰或 ssh-agent 登入",
 "저장된 비밀번호가 없어요. 비밀번호를 넣고 연결하세요.": "沒有已儲存的密碼。請輸入密碼後再連線。",
 "SSH 키 또는 비밀번호로 접속해요. 비밀번호는 이 PC의 키체인에 저장해 다시 묻지 않고, 연결 끊기를 누르면 지금 연결된 서버의 비밀번호를 지워요.": "使用 SSH 金鑰或密碼連線。密碼會儲存在這台電腦的金鑰鏈中，就不會再詢問；按下「中斷連線」會刪除目前連線伺服器的密碼。",
 "이 PC의 터미널에서 아래 명령으로 같은 비밀번호로 접속되는지 먼저 확인하세요.": "請先在這台電腦的終端機，用下面的指令確認能以同一組密碼登入。",
